    {"상황": "악한 환경에 있는 사람들을 도저히 용납할 수 없는 성도", "성경원리": "가장 악한 니느웨도 하나님은 포기하지 않으셨다 - 하나님의 보편적 사랑", "실제적용": "하나님의 시각으로 그들을 바라보는 훈련 - 기도를 통해 그들을 위한 마음을 구하도록 인도"},
    {"상황": "불의한 세상에 하나님이 침묵하신다고 느끼는 성도", "성경원리": "니느웨의 악독이 하나님 앞에 상달됨 - 하나님은 모든 불의를 보고 계신다", "실제적용": "하나님의 때를 기다리는 인내를 기르고, 자신의 역할(외치는 사명)을 감당하도록 격려"}
