    {"원어": "וַיִּירְאוּ יִרְאָה גְדוֹלָה (와이이레우 이르아 게돌라)", "의미_문법": "심히 두려워하여, 동사 반복 + 형용사 - 극도의 공포 표현", "설교포인트": "이방인이 여호와의 위대함에 극도로 경외함 - 요나보다 더 강한 반응"},
    {"원어": "מַה זֹּאת עָשִׂיתָ (마 조트 아시타)", "의미_문법": "네가 어찌하여 이렇게 행하였느냐, 수사의문문 - 강한 책망과 놀라움", "설교포인트": "도덕적 질책 - 하나님을 경외하는 자가 하나님을 피해 도망하는 것에 대한 비판"}
