  "표5_매튜헨리": [
    {"영어원문": "He told them that he fled from the presence of the LORD — a frank and full confession. He hid nothing; his fear of the sailors was overcome by his sense of guilt.", "한국어번역": "그는 자신이 여호와의 낯을 피해 도망쳤다고 그들에게 말했다 - 솔직하고 완전한 고백. 그는 아무것도 숨기지 않았다; 선원들에 대한 두려움이 죄책감에 의해 극복되었다.", "핵심통찰": "죄책감이 용기가 되어 진실을 말하게 한다 - 고백의 역설"},
    {"영어원문": "The men feared exceedingly — the heathen sailors were more afraid of the God of Israel than Jonah was. The messenger had less faith than those who received the message.", "한국어번역": "그 사람들이 심히 두려워하였다 - 이방 선원들이 이스라엘의 하나님을 요나보다 더 두려워했다. 사자가 메시지를 받은 자들보다 더 적은 믿음을 가졌다.", "핵심통찰": "하나님의 메시지를 전달하는 자가 받는 자보다 덜 경외할 수 있다"},
    {"영어원문": "Why hast thou done this? — Even the heathen could see that fleeing from God was irrational. Sometimes unbelievers have clearer moral vision than believers.", "한국어번역": "네가 어찌하여 이렇게 하였느냐 - 이방인들조차 하나님에게서 도망치는 것이 불합리하다는 것을 알았다. 때로 불신자들이 신자들보다 더 분명한 도덕적 판단력을 가진다.", "핵심통찰": "이방인도 신자의 불순종을 알아본다 - 신자의 이중성은 증언을 해친다"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "네가 어찌하여 이렇게 하였느냐 - 이방인의 정당한 질책", "예화_적용": ""},
    {"대지": "서론", "내용": "이방 선원들이 요나에게 묻는다. '네가 어찌하여 이렇게 하였느냐?' 하나님을 안다는 사람이 하나님을 피해 도망쳤다는 것이 이방인에게도 말이 안 된다. 우리의 불순종은 세상에도 설득력이 없다.", "예화_적용": "불신자가 기독교인의 위선을 비판할 때 - 그 비판이 때로 정당하다"},
    {"대지": "1대지: 요나가 고백한다 (자백의 용기)", "내용": "요나가 자신의 도망 이유를 스스로 고백한다. 강요받지 않았지만 진실을 말한다. 죄의 고백은 해방의 시작이다.", "예화_적용": "잘못을 인정하는 것이 자존심이 상하는 것이 아니라 진정한 용기"},
    {"대지": "2대지: 이방인이 더 두려워한다 (영적 역전)", "내용": "이방 선원들이 여호와를 심히 두려워한다. 요나보다 더 강한 반응. 때로 이방인이 신자보다 더 하나님을 경외할 수 있다.", "예화_적용": "예수님이 이스라엘에서 이방인의 믿음을 칭찬하신 것처럼 (마 8:10)"},
    {"대지": "3대지: 어찌하여 이렇게 하였느냐 (불순종의 이해 불가)", "내용": "이방인들도 요나의 행동이 납득되지 않는다. 세상도 신자의 불순종과 위선을 이해하지 못한다.", "예화_적용": "교회 지도자의 비윤리적 행동에 세상이 충격받는 이유 - 우리의 기준이 우리를 정죄한다"},
    {"대지": "결론", "내용": "당신의 삶이 세상에게도 정당한 질책을 받고 있는가? 이방인들이 당신의 행동을 보며 '어찌하여 이렇게 하였느냐'고 하지 않는가? 고백하고 돌이키라.", "예화_적용": ""}
  ],
