    {"새찬송가": "32장", "통일찬송가": "32장", "제목": "주 앞에 나아가 고백함", "선정이유": "죄를 고백하고 용서를 구하는 기도"},
    {"새찬송가": "521장", "통일찬송가": "359장", "제목": "죄 짐 맡은 우리 구주", "선정이유": "죄의 짐을 주님께 내려놓는 고백"},
    {"새찬송가": "305장", "통일찬송가": "405장", "제목": "나 같은 죄인 살리신", "선정이유": "죄인이 은혜로 구원받는 감사의 고백"}
