  "표5_매튜헨리": [
    {"영어원문": "They cried unto the LORD — not now to their own gods but to Jonah's God. Such was the effect of Jonah's testimony, even in his disobedience.", "한국어번역": "그들이 여호와께 부르짖었다 - 이제 자기들의 신이 아니라 요나의 하나님께. 이것이 그의 불순종 중에도 요나의 증언이 미친 효과였다.", "핵심통찰": "불완전한 증인을 통해서도 역사하시는 하나님"},
    {"영어원문": "Let not innocent blood be upon us — these mariners showed remarkable moral sensitivity. They were reluctant murderers, forced by necessity.", "한국어번역": "무죄한 피를 우리에게 돌리지 마소서 - 이 선원들은 놀라운 도덕적 감수성을 보였다. 그들은 필요에 의해 강요된 마지못한 살인자들이었다.", "핵심통찰": "이방인의 도덕적 감수성 - 하나님의 형상의 흔적"},
    {"영어원문": "For thou, O LORD, hast done as it pleased thee — a beautiful confession of God's sovereignty. Even pagans could acknowledge what many Christians deny.", "한국어번역": "여호와여, 당신은 당신이 기뻐하시는 대로 행하셨나이다 - 아름다운 하나님의 주권 고백. 이방인들조차 많은 그리스도인이 부인하는 것을 인정할 수 있었다.", "핵심통찰": "하나님의 주권을 인정하는 것이 진정한 신앙의 출발점"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "여호와여 구하고 구하오니 - 이방인의 기도에서 배우는 신앙", "예화_적용": ""},
    {"대지": "서론", "내용": "놀라운 장면이다. 이방 선원들이 여호와의 이름으로 기도한다. 자기 신에게 기도하던 그들이 이제 요나의 하나님 여호와께 부르짖는다. 위기가 진정한 예배자를 만들었다.", "예화_적용": "위기 중에 신앙을 갖게 된 사람들의 이야기 - 전쟁터에서 하나님을 만난 군인"},
    {"대지": "1대지: 여호와께 부르짖다 (진정한 기도의 대상)", "내용": "더 이상 바알이나 다곤이 아닌 여호와께 기도한다. 진짜 하나님을 알게 된 자만이 진짜 하나님께 기도할 수 있다.", "예화_적용": "우상들의 무력함을 경험하고 살아계신 하나님을 찾는 것"},
    {"대지": "2대지: 무죄한 피를 돌리지 마소서 (도덕적 각성)", "내용": "선원들이 요나를 죽이는 것의 도덕적 무게를 느낀다. 이것은 하나님의 형상이 인간 안에 남아있음의 증거.", "예화_적용": "하나님을 모르는 사람들 안에도 양심이 있다 - 일반 은총의 증거"},
    {"대지": "3대지: 주의 뜻대로 행하심이다 (주권 인정의 신앙)", "내용": "이방인들이 신앙의 핵심을 고백한다 - 하나님의 주권. 이것이 진정한 신앙 고백이다.", "예화_적용": "욥이 모든 것을 잃고도 여호와가 취하셨다 주의 이름이 찬송을 받으시기를 원한다고 한 것처럼"},
    {"대지": "결론", "내용": "이방 선원들이 한 기도를 당신도 할 수 있는가? 여호와여, 주의 뜻대로 행하심이니이다. 이 고백이 폭풍 속 진정한 평안을 가져온다.", "예화_적용": ""}
  ],
