    {"새찬송가": "549장", "통일찬송가": "493장", "제목": "나를 인도하소서", "선정이유": "하나님의 주권에 맡기는 기도"},
    {"새찬송가": "423장", "통일찬송가": "484장", "제목": "주 뜻대로 행하소서", "선정이유": "주의 뜻대로 행하심을 고백하는 찬양"}
