    {"항목": "예비된 구원의 도구", "내용": "'이미 준비하사' - 요나가 바다에 던져지기 전에 이미 물고기가 준비되어 있었다. 하나님의 구원은 우리의 위기보다 앞서 있다", "목회적활용": "하나님의 구원 준비는 우리의 필요보다 먼저이다"}
