    {"새찬송가": "338장", "통일찬송가": "338장", "제목": "내 주를 가까이 하게 함은", "선정이유": "고난이 하나님 가까이 이끄는 은혜"},
    {"새찬송가": "403장", "통일찬송가": "460장", "제목": "나의 힘이 되신 여호와여", "선정이유": "고난 중 힘이 되시는 여호와를 고백"},
    {"새찬송가": "363장", "통일찬송가": "420장", "제목": "내 기도하는 그 시간", "선정이유": "응답하시는 하나님께 드리는 기도"}
